document.addEventListener("DOMContentLoaded", () => {
    // Select cart items
    const cartItems = document.querySelectorAll(".flex.gap-6.items-start");
    
    const subtotalEl = document.querySelectorAll(".font-body-md.text-primary")[0];
    const totalEl = document.querySelectorAll(".font-headline-md.text-headline-md")[1];

    function parsePrice(text) {
        return parseFloat(text.replace("$", ""));
    }

    function updateTotal() {
        let subtotal = 0;

        cartItems.forEach(item => {
            const priceText = item.querySelector(".font-headline-md").textContent;
            const price = parsePrice(priceText);

            const qty = parseInt(item.querySelector(".px-4").textContent);

            subtotal += price * qty;
        });

        subtotalEl.textContent = `$${subtotal.toFixed(2)}`;
        totalEl.textContent = `$${subtotal.toFixed(2)}`;
    }

    cartItems.forEach(item => {
        const minusBtn = item.querySelector(".material-symbols-outlined.text-sm").parentElement;
        const plusBtn = item.querySelectorAll(".material-symbols-outlined.text-sm")[1].parentElement;
        const qtyEl = item.querySelector(".px-4");
        const removeBtn = item.querySelector(".material-symbols-outlined").parentElement;

        // Increase quantity
        plusBtn.addEventListener("click", () => {
            let qty = parseInt(qtyEl.textContent);
            qty++;
            qtyEl.textContent = qty;
            updateTotal();
        });

        // Decrease quantity
        minusBtn.addEventListener("click", () => {
            let qty = parseInt(qtyEl.textContent);
            if (qty > 1) {
                qty--;
                qtyEl.textContent = qty;
                updateTotal();
            }
        });

        // Remove item
        removeBtn.addEventListener("click", () => {
            item.remove();
            updateTotal();
        });
    });

    // Initial calculation
    updateTotal();
});
